import {format, styleText} from 'node:util'

import {Command, Interfaces, ux} from '@oclif/core'
import {CLIError, ExitError} from '@oclif/core/errors'
import {type CommandError, type Input, type ParserOutput} from '@oclif/core/interfaces'

import {subdebug} from './_exports/debug.js'
import {resolveUnattendedFlagRequirements} from './_exports/flags.js'
import {
  getGlobalCliClient,
  getProjectCliClient,
  type GlobalCliClientOptions,
  type ProjectCliClientOptions,
} from './apiClient.js'
import {getCliConfig} from './config/cli/getCliConfig.js'
import {type CliConfig} from './config/cli/types/cliConfig.js'
import {findProjectRoot} from './config/findProjectRoot.js'
import {type ProjectRootResult} from './config/util/recursivelyResolveProjectRoot.js'
import {enrichAuthError} from './errors/enrichAuthError.js'
import {JsonOutputError} from './errors/JsonOutputError.js'
import {NonInteractiveError} from './errors/NonInteractiveError.js'
import {ProjectRootNotFoundError} from './errors/ProjectRootNotFoundError.js'
import {getCliExecutionContext} from './executionContext.js'
import {exitCodes} from './exitCodes.js'
import {getCliTelemetry, reportCliTraceError} from './telemetry/getCliTelemetry.js'
import {type CLITelemetryStore} from './telemetry/types.js'
import {type Output} from './types.js'
import {isInteractive} from './util/isInteractive.js'
import {isUnattendedInvocation, isUnattended as resolveIsUnattended} from './util/isUnattended.js'
import {hasJsonFlagInArgv, toRelayableErrorJson} from './util/jsonInvocation.js'

type Flags<T extends typeof Command> = Interfaces.InferredFlags<
  (typeof SanityCommand)['baseFlags'] & T['flags']
>

type Args<T extends typeof Command> = Interfaces.InferredArgs<T['args']>

type ParserValues = Record<string, unknown>

const debug = subdebug('sanityCommand')

/**
 * Interface for `SanityCommand`, a wrapper around OCLIF's Command class.
 * Important to keep updated as `SanityCommand` evolves so that its mock implementation (enabling fast unit tests) stays up to date as well.
 * @see https://oclif.io/docs/base_class/
 */
export interface SanityCommandInterface {
  getCliConfig: () => Promise<CliConfig>
  getProjectId: (options?: {
    deprecatedFlagName?: string
    fallback?: () => Promise<string>
  }) => Promise<string>
  getProjectRoot: () => Promise<ProjectRootResult>
  isUnattended: () => boolean
  output: Output
  resolveIsInteractive: () => boolean
}

export abstract class SanityCommand<T extends typeof Command>
  extends Command
  implements SanityCommandInterface
{
  protected args!: Args<T>
  protected flags!: Flags<T>

  /**
   * Get the global API client.
   *
   * @param args - The global API client options.
   * @returns The global API client.
   *
   * @deprecated use `getGlobalCliClient` function directly instead.
   */
  protected getGlobalApiClient = (args: GlobalCliClientOptions) => getGlobalCliClient(args)

  /**
   * Get the project API client.
   *
   * @param args - The project API client options.
   * @returns The project API client.
   *
   * @deprecated use `getProjectCliClient` function directly instead.
   */
  protected getProjectApiClient = (args: ProjectCliClientOptions) => getProjectCliClient(args)

  /**
   * Helper for outputting to the console.
   *
   * @example
   * ```ts
   * this.output.log('Hello')
   * this.output.warn('Warning')
   * this.output.error('Error')
   * ```
   */
  public output: Output = {
    error: this.error.bind(this),
    log: this.log.bind(this),
    logDiagnostic: this.logDiagnostic.bind(this),
    logJson: this.logJson.bind(this),
    warn: this.warn.bind(this),
  }

  /**
   * The telemetry store.
   *
   * @returns The telemetry store.
   */
  protected telemetry!: CLITelemetryStore
  /**
   * Report real command errors to the CLI command trace.
   * User aborts (SIGINT, ExitPromptError) are not reported — the trace is left
   * incomplete, which accurately represents that the command was interrupted.
   */
  protected override async catch(err: CommandError): Promise<void> {
    // ExitPromptError is thrown by `@inquirer/prompts` when the user cancels a prompt
    // The `message === 'SIGINT'` check matches oclif's own convention (see handle.js in @oclif/core)
    const isUserAbort = err.name === 'ExitPromptError' || err.message === 'SIGINT'
    if (isUserAbort) {
      if (!this.jsonEnabled()) {
        this.logToStderr(styleText('yellow', '\u{203A}') + ' Aborted by user')
        return this.exit(exitCodes.SIGINT)
      }
      err = new CLIError('Aborted by user', {exit: exitCodes.SIGINT})
    }

    if (err instanceof ExitError) {
      if (err.oclif.exit !== exitCodes.SUCCESS) reportCliTraceError(err)
      if (getCliExecutionContext() || !this.jsonEnabled()) throw err
      process.exitCode = err.oclif.exit
      return
    }

    // 401s carry login/membership guidance in their message. Applied here
    // rather than in transport middleware since client v8 dropped custom
    // requesters.
    enrichAuthError(err)

    // In other cases, we _do_ want to report the error
    if (!isUserAbort) reportCliTraceError(err)

    // oclif's base `catch` sets `process.exitCode` as a side effect
    // we do not want to write to the host's own exit status.
    if (getCliExecutionContext()) {
      if (this.jsonEnabled()) {
        this.logJson(this.toErrorJson(err))
      }
      throw err
    }

    if (this.jsonEnabled()) {
      process.exitCode =
        err instanceof CLIError ? err.oclif.exit : (err.exitCode ?? exitCodes.RUNTIME_ERROR)
    }
    return super.catch(err)
  }

  /**
   * Get the CLI config.
   *
   * @returns The CLI config.
   */
  public async getCliConfig(): Promise<CliConfig> {
    const root = await this.getProjectRoot()

    debug(`Using project root`, root)
    return getCliConfig(root.directory)
  }

  /**
   * Get the project ID from passed flags or (if not provided) the CLI config.
   *
   * Optionally accepts a `fallback` function that is called when no project ID
   * can be determined from flags or config. This allows commands to provide
   * interactive project selection while keeping the prompt logic in the CLI package.
   *
   * If the fallback throws a `NonInteractiveError` (e.g. because the terminal is
   * not interactive), it falls through to the standard error with suggestions.
   *
   * Optionally accepts a `deprecatedFlagName` for commands that have a deprecated
   * flag that should be checked after `--project` but before the CLI config.
   *
   * @returns The project ID.
   */
  public async getProjectId(options?: {
    deprecatedFlagName?: string
    fallback?: () => Promise<string>
  }): Promise<string> {
    const hasProjectFlag = this.ctor.flags != null && 'project' in this.ctor.flags

    // Check --project flag first
    if (hasProjectFlag) {
      const flagProjectId =
        'project' in this.flags && typeof this.flags.project === 'string'
          ? this.flags.project
          : undefined

      if (flagProjectId) return flagProjectId
    }

    // Check deprecated flag before CLI config
    if (options?.deprecatedFlagName) {
      const deprecatedValue =
        options.deprecatedFlagName in this.flags &&
        typeof this.flags[options.deprecatedFlagName] === 'string'
          ? (this.flags[options.deprecatedFlagName] as string)
          : undefined

      if (deprecatedValue) return deprecatedValue
    }

    // Fall back to CLI config
    try {
      const config = await this.getCliConfig()
      const configProjectId = config.api?.projectId
      if (configProjectId) return configProjectId
    } catch (err) {
      if (!(err instanceof ProjectRootNotFoundError)) throw err
      // No project root — fall through to fallback/error
    }

    // Offer interactive selection if a fallback was provided
    if (options?.fallback) {
      try {
        return await options.fallback()
      } catch (err) {
        if (!(err instanceof NonInteractiveError)) throw err
        // Non-interactive: throw with actionable suggestions
        throw new ProjectRootNotFoundError('Unable to determine project ID', {
          cause: err,
          suggestions: [
            ...(hasProjectFlag ? ['Providing a project ID: --project <project-id>'] : []),
            'Running this command from within a Sanity project directory',
            'Running in an interactive terminal to get a project selection prompt',
          ],
        })
      }
    }

    throw new ProjectRootNotFoundError('Unable to determine project ID', {
      suggestions: [
        ...(hasProjectFlag ? ['Providing a project ID: --project <project-id>'] : []),
        'Running this command from within a Sanity project directory',
      ],
    })
  }

  /**
   * Get the project's root directory by resolving the config
   *
   * @returns The project root result.
   */
  public getProjectRoot(): Promise<ProjectRootResult> {
    if (getCliExecutionContext()) {
      throw new ProjectRootNotFoundError(
        'Project root resolution from the filesystem is disabled for programmatic invocations',
      )
    }
    return findProjectRoot(process.cwd())
  }

  public async init(): Promise<void> {
    const {args, flags} = await this.parse({
      args: this.ctor.args,
      baseFlags: (super.ctor as typeof SanityCommand).baseFlags,
      enableJsonFlag: this.ctor.enableJsonFlag,
      flags: this.ctor.flags,
      strict: this.ctor.strict,
    })

    this.args = args as Args<T>
    this.flags = flags as Flags<T>
    this.telemetry = getCliTelemetry()

    await super.init()
  }

  /**
   * Check if the command is running in unattended mode.
   *
   * This means the command should not ask for user input, instead using defaults where
   * possible, and if that does not make sense (eg there's missing information), then we
   * should error out (remember to exit with a non-zero code).
   *
   * Most commands should take an explicit `--yes` flag to enable unattended mode, but
   * some commands may also be run in unattended mode if `process.stdin` is not a TTY
   * (eg when running in a CI environment), or when `--json` asks for machine-readable
   * output (a caller parsing JSON can't answer a prompt).
   */
  public isUnattended(): boolean {
    return resolveIsUnattended({
      isInteractive: this.resolveIsInteractive(),
      json: this.flags.json,
      yes: this.flags.yes,
    })
  }

  /**
   * Whether this run should emit JSON.
   *
   * oclif's own check also treats `SANITY_CONTENT_TYPE=json` as a request for
   * JSON. That reads the host process's environment, so it is consulted only
   * for a real command line: a programmatic invocation must decide from its own
   * arguments, never from whatever the embedding process happens to export.
   */
  public override jsonEnabled(): boolean {
    if (!this.ctor.enableJsonFlag) return false
    if (this.flags) return Boolean(this.flags.json)

    if (!getCliExecutionContext() && super.jsonEnabled()) return true
    return hasJsonFlagInArgv(this.argv, {...this.ctor.baseFlags, ...this.ctor.flags})
  }

  /**
   * Write to stdout — or, when running under an execution context (e.g. from
   * an MCP server), to the context's `stdout` sink. Mirrors oclif's `log`
   * semantics: suppressed when `--json` is enabled, printf-style formatting.
   */
  public override log(message = '', ...args: unknown[]): void {
    const context = getCliExecutionContext()
    if (!context?.stdout) {
      super.log(message, ...args)
      return
    }
    if (!this.jsonEnabled()) context.stdout(format(message, ...args))
  }

  /**
   * Write a diagnostic that stays visible in JSON mode.
   *
   * `log`, `warn` and `logToStderr` are all suppressed once `--json` is on, so
   * a command that skipped part of its work would report the remainder as a
   * complete result. stderr carries it instead, where it cannot corrupt the
   * payload: JSON mode is reachable only from a real command line, since
   * programmatic invocations drop the flag.
   */
  public logDiagnostic(message: string): void {
    const context = getCliExecutionContext()
    if (context?.stderr) {
      context.stderr(message)
      return
    }
    ux.stderr(message)
  }

  /**
   * Pretty-print JSON to stdout — or plain (un-colorized) JSON to the
   * execution context's `stdout` sink, so programmatic callers don't have to
   * strip ANSI codes.
   */
  public override logJson(json: unknown): void {
    const context = getCliExecutionContext()
    if (!context?.stdout) {
      super.logJson(json)
      return
    }
    context.stdout(JSON.stringify(json, null, 2))
  }

  /**
   * Like `log`, but for stderr / the context's `stderr` sink.
   */
  public override logToStderr(message = '', ...args: unknown[]): void {
    const context = getCliExecutionContext()
    if (!context?.stderr) {
      super.logToStderr(message, ...args)
      return
    }
    if (!this.jsonEnabled()) context.stderr(format(message, ...args))
  }

  protected override async parse<
    F extends ParserValues,
    B extends ParserValues,
    A extends ParserValues,
  >(options?: Input<F, B, A>, argv: string[] = this.argv): Promise<ParserOutput<F, B, A>> {
    let resolvedOptions = options
    const jsonEnabled = this.jsonEnabled()

    if (options?.flags) {
      const resolvedFlags = resolveUnattendedFlagRequirements(
        options.flags,
        jsonEnabled || isUnattendedInvocation({argv, isInteractive: this.resolveIsInteractive()}),
      )
      if (resolvedFlags !== options.flags) {
        resolvedOptions = {...options, flags: resolvedFlags as Interfaces.FlagInput<F>}
      }
    }

    const parsed = await super.parse(resolvedOptions, argv)
    const jsonFlag = Boolean(parsed.flags.json) || jsonEnabled

    parsed.flags = {...parsed.flags, json: jsonFlag}
    return parsed
  }

  /**
   * Resolver for checking if the terminal is interactive. Override in tests to provide mock values.
   *
   * @returns Whether the terminal is interactive.
   */
  public resolveIsInteractive(): boolean {
    return isInteractive()
  }

  /**
   * Execute an already-constructed command without oclif's static runner:
   * `Command.run()` performs a full `Config.load()` — filesystem reads, env
   * consultation, and a process-global config cache write — on every call,
   * which programmatic invocations must not repeat per request.
   */
  public runInExecutionContext<TResult>(): Promise<TResult> {
    if (!getCliExecutionContext()) {
      throw new Error('runInExecutionContext requires a CLI execution context')
    }
    return this._run<TResult>()
  }

  /**
   * A command-specific report wins; otherwise oclif's envelope, trimmed to a
   * bounded set of properties when a programmatic caller will relay it. See
   * {@link toRelayableErrorJson} for why the untrimmed form is unsafe there.
   */
  public override toErrorJson(err: unknown): unknown {
    if (err instanceof JsonOutputError) return err.payload
    if (getCliExecutionContext()) return toRelayableErrorJson(err)
    return super.toErrorJson(err)
  }

  /**
   * Get the CLI config, returning an empty config if no project root is found.
   *
   * Use this instead of `getCliConfig()` in commands that can operate without a
   * project directory (e.g. when `--project` and `--dataset` flags are provided).
   *
   * @returns The CLI config, or an empty config object if no project root is found.
   */
  protected async tryGetCliConfig(): Promise<CliConfig> {
    try {
      return await this.getCliConfig()
    } catch (err) {
      if (!(err instanceof ProjectRootNotFoundError)) throw err
      return {}
    }
  }

  /**
   * Emit a warning — routed to the execution context's `stderr` sink when one
   * is active, otherwise through oclif's standard warning printer.
   */
  public override warn(input: Error | string): Error | string {
    const context = getCliExecutionContext()
    if (!context?.stderr) return super.warn(input)

    if (!this.jsonEnabled()) {
      context.stderr(`Warning: ${input instanceof Error ? input.message : input}`)
    }
    return input
  }

  protected override warnIfFlagDeprecated(flags: Record<string, unknown>): void {
    super.warnIfFlagDeprecated(flags)

    // oclif only warns for aliases passed as separate tokens, missing --alias=value.
    const flagArgs = this.argv.slice(
      0,
      this.argv.includes('--') ? this.argv.indexOf('--') : undefined,
    )
    for (const name of Object.keys(flags)) {
      const flag = this.ctor.flags?.[name]
      if (!flag?.deprecateAliases) continue

      for (const alias of flag.aliases ?? []) {
        if (flagArgs.some((arg) => arg.startsWith(`--${alias}=`))) {
          this.warn(`The --${alias} flag is deprecated. Use --${name} instead.`)
        }
      }
    }
  }
}
